import re,html
t=open('/tmp/zw.html',encoding='utf-8',errors='replace').read()
# search raw for rows with a date and count
for m in re.finditer(r'(20(?:25|26)-[01][0-9][^\n]{0,120})',t):
    seg=m.group(1)
    if re.search(r'7,2[0-9]{2},[0-9]{3}',seg): print(seg[:150])
print('---tables---')
for m in re.finditer(r'<tr[^>]*>(.*?)</tr>',t,re.S):
    row=re.sub(r'<[^>]+>','|',html.unescape(m.group(1)))
    if re.search(r'7,2[0-9]{2},[0-9]{3}',row) and re.search(r'202[45-9]',row): print(re.sub(r'(\|\s*)+','|',row)[:160])
EOF

